-- #638/#647. Prepared additive migration; no historical scores are published.
begin;
set local lock_timeout='5s';
create table lumen_commands.ranking_control (
 singleton boolean primary key default true check(singleton),activated_at timestamptz not null default clock_timestamp()
);
insert into lumen_commands.ranking_control(singleton) values(true);
alter table lumen_commands.ranking_control enable row level security;
revoke all on lumen_commands.ranking_control from public,anon,authenticated;
alter table lumen_commands.quest_rules add column ranking_reference_seconds integer not null default 180 check(ranking_reference_seconds between 10 and 86400);
create table lumen_commands.ranking_members (
 user_id uuid primary key references auth.users(id) on delete cascade,
 nickname text not null check(char_length(nickname) between 2 and 24 and nickname !~ '[@[:cntrl:]]'),
 participating boolean not null default false
);
create table lumen_commands.ranking_runs (
 user_id uuid not null references auth.users(id) on delete cascade,
 operation_id text not null check(operation_id ~ '^[A-Za-z0-9._-]{1,120}$'),
 quest_id text not null references lumen_commands.quest_rules(quest_id),grid_revision integer not null,
 started_at timestamptz not null,issued_at timestamptz not null default clock_timestamp(),
 eligible boolean not null,counts jsonb,result jsonb,
 primary key(user_id,operation_id)
);
create index ranking_runs_cooldown on lumen_commands.ranking_runs(user_id,quest_id,grid_revision,issued_at desc) where eligible;
create table lumen_commands.ranking_scores (
 user_id uuid not null references auth.users(id) on delete cascade,
 quest_id text not null references lumen_commands.quest_rules(quest_id),grid_revision integer not null,
 seconds integer not null check(seconds>=0),penalty integer not null check(penalty>=0),
 score integer generated always as (seconds+penalty) stored,
 primary key(user_id,quest_id,grid_revision)
);
create index ranking_scores_order on lumen_commands.ranking_scores(quest_id,grid_revision,score,user_id);
alter table lumen_commands.ranking_members enable row level security;
alter table lumen_commands.ranking_runs enable row level security;
alter table lumen_commands.ranking_scores enable row level security;
revoke all on lumen_commands.ranking_members,lumen_commands.ranking_runs,lumen_commands.ranking_scores from public,anon,authenticated;

create function lumen_commands.ranking_membership(p_enabled boolean,p_nickname text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();
begin
 if u is null then raise insufficient_privilege;end if;
 perform pg_advisory_xact_lock(hashtextextended('ranking:'||u::text,0));
 if p_enabled is null then raise invalid_parameter_value;end if;
 if p_enabled then
  if p_nickname is null or char_length(btrim(p_nickname)) not between 2 and 24 or p_nickname ~ '[@[:cntrl:]]' then raise invalid_parameter_value;end if;
  insert into lumen_commands.ranking_members values(u,btrim(p_nickname),true)
   on conflict(user_id) do update set nickname=excluded.nickname,participating=true;
 else
  delete from lumen_commands.ranking_scores where user_id=u;
  delete from lumen_commands.ranking_members where user_id=u;
 end if;
 return jsonb_build_object('participating',p_enabled);
end $$;

create function lumen_commands.ranking_begin(p_operation_id text,p_quest_id text,p_grid_revision integer,p_started_at timestamptz) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();r lumen_commands.ranking_runs%rowtype;last_run lumen_commands.ranking_runs%rowtype;current_revision integer;allowed boolean;
begin
 if u is null then raise insufficient_privilege;end if;
 if p_operation_id is null or p_operation_id !~ '^[A-Za-z0-9._-]{1,120}$' or p_started_at is null or not isfinite(p_started_at)
  or p_started_at>clock_timestamp()+interval '5 seconds' then raise invalid_parameter_value;end if;
 select grid_revision into current_revision from lumen_commands.quest_rules where quest_id=p_quest_id;
 if not found or p_grid_revision is distinct from current_revision then raise invalid_parameter_value;end if;
 if p_started_at<(select activated_at from lumen_commands.ranking_control) then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended('ranking:'||u::text,0));
 select * into r from lumen_commands.ranking_runs where user_id=u and operation_id=p_operation_id;
 if found then
  if r.quest_id<>p_quest_id or r.grid_revision<>p_grid_revision or r.started_at<>p_started_at then raise invalid_parameter_value;end if;
  return jsonb_build_object('eligible',r.eligible);
 end if;
 select * into last_run from lumen_commands.ranking_runs where user_id=u and quest_id=p_quest_id and grid_revision=p_grid_revision and eligible order by issued_at desc limit 1;
 allowed:=last_run.operation_id is null or (p_started_at>=last_run.started_at+interval '15 minutes' and clock_timestamp()>=last_run.issued_at+interval '15 minutes');
 insert into lumen_commands.ranking_runs(user_id,operation_id,quest_id,grid_revision,started_at,eligible) values(u,p_operation_id,p_quest_id,p_grid_revision,p_started_at,allowed);
 return jsonb_build_object('eligible',allowed);
end $$;

create function lumen_commands.ranking_finish(p_operation_id text,p_hint_uses integer,p_verify_uses integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();r lumen_commands.ranking_runs%rowtype;request jsonb;facts jsonb;raw integer;penalty integer;old_score integer;improved boolean;v_counts jsonb;res jsonb;
begin
 if u is null then raise insufficient_privilege;end if;
 if p_hint_uses is null or p_verify_uses is null or p_hint_uses not between 0 and 10000 or p_verify_uses not between 0 and 10000 then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended('ranking:'||u::text,0));
 select * into r from lumen_commands.ranking_runs where user_id=u and operation_id=p_operation_id for update;
 if not found then raise invalid_parameter_value;end if;
 v_counts:=jsonb_build_object('hint',p_hint_uses,'verify',p_verify_uses);
 if r.result is not null then
  if r.counts is distinct from v_counts then raise invalid_parameter_value;end if;
  return r.result||jsonb_build_object('improved',false);
 end if;
 if not exists(select 1 from lumen_commands.ranking_members where user_id=u and participating) then return jsonb_build_object('status','membership_required');end if;
 select c.request into request from lumen_commands.canonical_receipts c where c.user_id=u and c.operation_id=p_operation_id;
 if request is null then select c.request into request from lumen_commands.legacy_receipts c where c.user_id=u and c.operation_id=p_operation_id;end if;
 if request is null then return jsonb_build_object('status','pending');end if;
 if request->>'questId' is distinct from r.quest_id then raise invalid_parameter_value;end if;
 facts:=request->'facts';
 if facts is null or (facts->>'qualifiedAt')::timestamptz<>r.started_at or (facts->>'hintUsed')::boolean<>(p_hint_uses>0)
  or (not (facts->>'assistanceUsed')::boolean and p_hint_uses+p_verify_uses>0) then raise invalid_parameter_value;end if;
 raw:=(facts->>'seconds')::integer;
 if raw<0 or raw>extract(epoch from clock_timestamp()-r.started_at)+5 then raise invalid_parameter_value;end if;
 if not r.eligible or not (facts->>'qualifying')::boolean or not exists(select 1 from lumen_commands.quest_rules where quest_id=r.quest_id and grid_revision=r.grid_revision) then
  res:=jsonb_build_object('status','ineligible','questId',r.quest_id,'improved',false);
 else
  penalty:=p_hint_uses*15+p_verify_uses*5;
  select score into old_score from lumen_commands.ranking_scores where user_id=u and quest_id=r.quest_id and grid_revision=r.grid_revision;
  improved:=old_score is null or raw+penalty<old_score;
  if improved then
   insert into lumen_commands.ranking_scores(user_id,quest_id,grid_revision,seconds,penalty) values(u,r.quest_id,r.grid_revision,raw,penalty)
    on conflict(user_id,quest_id,grid_revision) do update set seconds=excluded.seconds,penalty=excluded.penalty;
  end if;
  res:=jsonb_build_object('status','confirmed','questId',r.quest_id,'improved',improved);
 end if;
 update lumen_commands.ranking_runs set counts=v_counts,result=res where user_id=u and operation_id=p_operation_id;
 return res;
end $$;

create function lumen_commands.ranking_board(p_quest_id text,p_grid_revision integer) returns jsonb
language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();reference integer;result jsonb;
begin
 if u is null then raise insufficient_privilege;end if;
 select ranking_reference_seconds into reference from lumen_commands.quest_rules where quest_id=p_quest_id and grid_revision=p_grid_revision;
 if not found then raise invalid_parameter_value;end if;
 with humans as (
  select s.user_id::text as key,m.nickname,s.score,s.seconds,s.penalty,s.user_id=u as mine,false as virtual
  from lumen_commands.ranking_scores s join lumen_commands.ranking_members m using(user_id)
  where s.quest_id=p_quest_id and s.grid_revision=p_grid_revision and m.participating
 ), echoes as (
  select 'echo-'||i as key,'Écho '||(array['Alcyone','Atlas','Maïa','Mérope','Électre','Taygète','Céléno','Pléioné','Astérope','Séléné'])[i] as nickname,
   (reference*(0.65+i*0.13))::integer as score,(reference*(0.65+i*0.13))::integer as seconds,0 as penalty,false as mine,true as virtual
  from generate_series(1,greatest(0,10-(select count(*)::integer from humans))) i
 ), ranked as (
  select *,rank() over(order by score) as place,row_number() over(order by score,key collate "C") as position from (select * from humans union all select * from echoes) all_rows
 ), scope as (
  select coalesce((select position from ranked where mine),1) as pos,(select count(*) from ranked) as total
 ), windowed as (
  select r.* from ranked r cross join scope s where
   (s.pos<=10 and r.position<=10) or (s.pos>10 and (r.position=1 or r.position between greatest(2,least(s.pos-5,s.total-9)) and greatest(2,least(s.pos-5,s.total-9))+9))
 ) select jsonb_build_object('participating',exists(select 1 from lumen_commands.ranking_members where user_id=u and participating),
  'rows',coalesce(jsonb_agg(jsonb_build_object('nickname',nickname,'score',score,'seconds',seconds,'penalty',penalty,'mine',mine,'virtual',virtual,'place',place,'position',position) order by position),'[]')) into result from windowed;
 return result;
end $$;

-- Privileged bodies are private. Public API wrappers do not bypass permissions.
revoke all on function lumen_commands.ranking_membership(boolean,text),lumen_commands.ranking_begin(text,text,integer,timestamptz),lumen_commands.ranking_finish(text,integer,integer),lumen_commands.ranking_board(text,integer) from public,anon,authenticated;
grant execute on function lumen_commands.ranking_membership(boolean,text),lumen_commands.ranking_begin(text,text,integer,timestamptz),lumen_commands.ranking_finish(text,integer,integer),lumen_commands.ranking_board(text,integer) to authenticated;
create function public.lumen_ranking_membership(p_enabled boolean,p_nickname text default null) returns jsonb language sql security invoker set search_path='' as $$select lumen_commands.ranking_membership(p_enabled,p_nickname)$$;
create function public.lumen_ranking_begin(p_operation_id text,p_quest_id text,p_grid_revision integer,p_started_at timestamptz) returns jsonb language sql security invoker set search_path='' as $$select lumen_commands.ranking_begin(p_operation_id,p_quest_id,p_grid_revision,p_started_at)$$;
create function public.lumen_ranking_finish(p_operation_id text,p_hint_uses integer,p_verify_uses integer) returns jsonb language sql security invoker set search_path='' as $$select lumen_commands.ranking_finish(p_operation_id,p_hint_uses,p_verify_uses)$$;
create function public.lumen_ranking_board(p_quest_id text,p_grid_revision integer) returns jsonb language sql security invoker set search_path='' as $$select lumen_commands.ranking_board(p_quest_id,p_grid_revision)$$;
revoke all on function public.lumen_ranking_membership(boolean,text),public.lumen_ranking_begin(text,text,integer,timestamptz),public.lumen_ranking_finish(text,integer,integer),public.lumen_ranking_board(text,integer) from public,anon,authenticated;
grant execute on function public.lumen_ranking_membership(boolean,text),public.lumen_ranking_begin(text,text,integer,timestamptz),public.lumen_ranking_finish(text,integer,integer),public.lumen_ranking_board(text,integer) to authenticated;

-- Extend the existing owner inventory, export and anti-resurrection guards.
alter function lumen_privacy.policy() rename to policy_before_ranking_638;
create function lumen_privacy.policy()
returns table(ns text,rel text,uid_col text,actor_col text,key_col text,action text)
language sql stable set search_path='' as $$
 select * from lumen_privacy.policy_before_ranking_638()
 union all select 'lumen_commands',x,'user_id',null,null,'delete'
 from unnest(array['ranking_members','ranking_runs','ranking_scores']) x
 union all select 'lumen_commands','ranking_control',null,null,null,'retain-rule';
$$;
revoke all on function lumen_privacy.policy(),lumen_privacy.policy_before_ranking_638() from public,anon,authenticated,service_role;
select lumen_privacy.install_guards();

